import{_ as u,a0 as r,w as i,s as p,ao as m,I as s,x as n,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const z=JSON.parse('{"title":"禁用Ubuntu 13.10的Amazon及遠程內容獲取 | LCTT x X-CMD","titleTemplate":false,"description":"禁用Ubuntu 13.10的Amazon及遠程內容獲取 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"禁用Ubuntu 13.10的Amazon及遠程內容獲取 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"禁用Ubuntu 13.10的Amazon及遠程內容獲取 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10","title":"禁用Ubuntu 13.10的Amazon及遠程內容獲取","tag":"201311","desc":""},"relativePath":"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10.md","filePath":"[post].md"}'),l={name:"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10.md"};function b(d,t,T,f,g,C){const e=r("Link");return i(),p("div",null,[t[11]||(t[11]=m(`<h1 id="禁用ubuntu-13-10的amazon及遠程內容獲取" tabindex="-1">禁用Ubuntu 13.10的Amazon及遠程內容獲取 <a class="header-anchor" href="#禁用ubuntu-13-10的amazon及遠程內容獲取" aria-label="Permalink to “禁用Ubuntu 13.10的Amazon及遠程內容獲取”">​</a></h1><p>Ubuntu 13.10已經發布一段時間了，是時候坐下來配置一下系統來滿足你的要求。Ubuntu 13.10配備了很多東西，當你安裝或者升級時其實有些並不是你所需要的。</p><p>舉個例子，當你安裝或者升級到Ubuntu 13.10時，會自動啓用Amazon和一些其他商業購物網站的功能。當你打開Unity Dash時這些Lens就會顯示。當你在Dash處執行搜索時，類似Amazon的遠程數據源中符合你搜索內容的選項也會發送過來。</p><p>這些由Canonical公司提供的新增特性可能對某些人有用，但是對另一些用户，這些特性可能是他們不需要的。</p><p>因為從遠程數據源獲取內容需要帶寬，這就可能會對你的上網賬單有負面影響，特別是當你住在一個根據流量計費的地域。</p><p>對於另一些對安全和隱私有擔憂的用户來説，本地自動搜索遠程源可能不是一個好主意。還有一些用户只是不想當他們在本地搜索時會有商業公司展示他們的產品。</p><p>這篇簡單的教程就是教你當使用Ubuntu 13.10時如何快速禁用Amazon和所有遠程內容獲取。</p><p>在你的鍵盤上按組合鍵 <strong>Ctrl – Alt – T</strong> 顯示終端。當它打開後運行下面的命令去禁用該功能。</p><pre><code>gsettings set com.canonical.Unity.Lenses remote-content-search &#39;none&#39;
</code></pre><p>如果你想要重新啓用它，運行以下命令。</p><pre><code>gsettings set com.canonical.Unity.Lenses remote-content-search &#39;all&#39;
</code></pre><p>你需要重新登陸或者重啓你的電腦使更改生效。在完成這些操作後，當你使用Ubuntu搜索時就沒有遠程源會被使用。</p><p>Enjoy!</p><hr>`,14)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.liberiangeek.net/2013/10/disable-amazon-remote-content-fetching-ubuntu-13-10/"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/10/disable-amazon-remote-content-fetching-ubuntu-13-10/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("譯者：",-1)),o(e,{href:"https://github.com/whatever1992"},{default:a(()=>[...t[2]||(t[2]=[n("whatever1992",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const _=u(l,[["render",b]]);export{z as __pageData,_ as default};
